-- ================================================================
-- Sprint 14 Fix: Add Missing Cartridge Prompts for ALL Destinations
-- Date: 2026-02-20
-- ================================================================
-- Problem: Projects with target technologies other than Databricks/Fabric
--          get 404 errors when loading cartridge prompts
-- Solution: Insert Bronze/Silver/Gold cartridges for:
--           - Snowflake (SQL-based)
--           - BigQuery (SQL-based)
--           - AWS Glue (PySpark-based)
--           - Redshift (SQL-based)
-- ================================================================

-- ================================================================
-- SNOWFLAKE CARTRIDGES (SQL-Based)
-- ================================================================

-- 1. Snowflake Bronze
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_snowflake_bronze',
    E'# Snowflake SQL Bronze Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS (Zero-Hardcode Policy)\n\n### 1. MANDATORY L2L MODERNIZATION TRACE HEADER\n```sql\n-- ================================================================\n-- L2L MODERNIZATION TRACE: Bronze Layer - {{asset_name}}\n-- ================================================================\n-- Source Asset: {{source_asset_name}}\n-- Source Technology: {{source_tech}}\n-- Target Platform: Snowflake (SQL + Snowpipe)\n-- Medallion Layer: Bronze\n-- Component Type: Data Pipeline\n-- Business Entity: {{business_entity}}\n-- Load Strategy: {{load_strategy}}\n-- Generated At: {{timestamp}}\n-- Generated By: L2L Agent-C (Cartridge: SnowflakeBronze v4.0)\n-- ================================================================\n```\n\n### 2. ZERO-HARDCODE CONFIGURATION\n**❌ FORBIDDEN:**\n- NO hardcoded database/schema: `USE DATABASE production;`\n- NO hardcoded table names: `INSERT INTO bronze.customers`\n- NO hardcoded credentials in COPY commands\n\n**✅ REQUIRED: Use variables from orchestrator**\n```sql\n-- Variables injected by orchestrator\nSET bronze_database = ''{{ bronze_database }}'';\nSET bronze_schema = ''{{ bronze_schema }}'';\nSET bronze_table = ''{{ bronze_table }}'';\nSET source_stage = ''{{ source_stage }}'';\n```\n\n### 3. BRONZE LAYER PATTERN\n```sql\n-- Create Bronze table with metadata columns\nCREATE TABLE IF NOT EXISTS IDENTIFIER($bronze_database || ''.'' || $bronze_schema || ''.'' || $bronze_table) (\n    -- Source columns (from metadata)\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    \n    -- Bronze metadata columns\n    _ingestion_timestamp TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),\n    _source_file VARCHAR,\n    _record_hash VARCHAR(64)\n);\n\n-- Load data using COPY INTO (idempotent)\nCOPY INTO IDENTIFIER($bronze_database || ''.'' || $bronze_schema || ''.'' || $bronze_table)\nFROM @IDENTIFIER($source_stage)\nFILE_FORMAT = (TYPE = ''CSV'' SKIP_HEADER = 1)\nON_ERROR = ''CONTINUE''\nFORCE = FALSE;  -- Prevents duplicate loads\n\n-- Track row counts\nSELECT ''LOADED'' AS status, COUNT(*) AS row_count \nFROM IDENTIFIER($bronze_database || ''.'' || $bronze_schema || ''.'' || $bronze_table)\nWHERE _ingestion_timestamp >= DATEADD(minute, -5, CURRENT_TIMESTAMP());\n```\n\n### 4. VALIDATION CHECKLIST\n- ✅ Header with L2L MODERNIZATION TRACE\n- ✅ No hardcoded database/schema/table names\n- ✅ Bronze metadata: `_ingestion_timestamp`, `_source_file`, `_record_hash`\n- ✅ COPY INTO with FORCE=FALSE (idempotent)\n- ✅ Row count tracking',
    true, 'agent-c', 'snowflake', 'bronze',
    '{"description": "Snowflake Bronze Layer cartridge (raw data ingestion with Medallion pattern)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 2. Snowflake Silver
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_snowflake_silver',
    E'# Snowflake SQL Silver Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS\n\n### 1. HEADER\n```sql\n-- ================================================================\n-- L2L MODERNIZATION TRACE: Silver Layer - {{asset_name}}\n-- Target Platform: Snowflake (SQL)\n-- Medallion Layer: Silver\n-- ================================================================\n```\n\n### 2. SILVER LAYER PATTERN (Cleansing + Deduplication)\n```sql\n-- Create Silver table\nCREATE TABLE IF NOT EXISTS IDENTIFIER($silver_database || ''.'' || $silver_schema || ''.'' || $silver_table) (\n    -- Business columns\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    \n    -- Silver metadata\n    _processed_timestamp TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),\n    _is_current BOOLEAN DEFAULT TRUE,\n    _silver_layer VARCHAR DEFAULT ''silver''\n);\n\n-- MERGE for SCD Type 1\nMERGE INTO IDENTIFIER($silver_database || ''.'' || $silver_schema || ''.'' || $silver_table) AS target\nUSING (\n    SELECT DISTINCT\n        *,\n        ROW_NUMBER() OVER (PARTITION BY {{business_key}} ORDER BY _ingestion_timestamp DESC) AS rn\n    FROM IDENTIFIER($bronze_database || ''.'' || $bronze_schema || ''.'' || $bronze_table)\n    WHERE _ingestion_timestamp > $last_run_timestamp\n) AS source\nON {{#each business_keys}}target.{{this}} = source.{{this}}{{#unless @last}} AND {{/unless}}{{/each}}\nWHEN MATCHED THEN UPDATE SET *\nWHEN NOT MATCHED THEN INSERT *;\n```\n\n### 3. VALIDATION\n- ✅ Read from Bronze table\n- ✅ Deduplication using business keys\n- ✅ MERGE operation for SCD Type 1\n- ✅ Silver metadata columns',
    true, 'agent-c', 'snowflake', 'silver',
    '{"description": "Snowflake Silver Layer cartridge (cleaned and deduplicated)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 3. Snowflake Gold
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_snowflake_gold',
    E'# Snowflake SQL Gold Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS\n\n### 1. HEADER\n```sql\n-- ================================================================\n-- L2L MODERNIZATION TRACE: Gold Layer - {{asset_name}}\n-- Target Platform: Snowflake (SQL)\n-- Medallion Layer: Gold\n-- ================================================================\n```\n\n### 2. GOLD LAYER PATTERN (Aggregations + Business Logic)\n```sql\n-- Create Gold table (Fact/Dimension)\nCREATE TABLE IF NOT EXISTS IDENTIFIER($gold_database || ''.'' || $gold_schema || ''.'' || $gold_table) (\n    -- Dimension/Fact columns\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    \n    -- Gold metadata\n    _gold_processed_timestamp TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),\n    _aggregation_level VARCHAR,\n    _last_refreshed TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()\n);\n\n-- Insert aggregated data\nINSERT INTO IDENTIFIER($gold_database || ''.'' || $gold_schema || ''.'' || $gold_table)\nSELECT\n    -- Business logic transformations\n    {{#each aggregations}}\n    {{expression}} AS {{alias}},\n    {{/each}}\n    CURRENT_TIMESTAMP() AS _gold_processed_timestamp,\n    ''{{aggregation_level}}'' AS _aggregation_level,\n    CURRENT_TIMESTAMP() AS _last_refreshed\nFROM IDENTIFIER($silver_database || ''.'' || $silver_schema || ''.'' || $silver_table)\nGROUP BY {{group_by_columns}};\n```\n\n### 3. VALIDATION\n- ✅ Read from Silver table(s)\n- ✅ Business logic aggregations\n- ✅ Gold metadata columns\n- ✅ Optimized for analytics',
    true, 'agent-c', 'snowflake', 'gold',
    '{"description": "Snowflake Gold Layer cartridge (business-ready aggregated data)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- ================================================================
