-- 4. BigQuery Bronze
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_bigquery_bronze',
    E'# BigQuery SQL Bronze Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS\n\n### 1. HEADER\n```sql\n-- ================================================================\n-- L2L MODERNIZATION TRACE: Bronze Layer - {{asset_name}}\n-- Target Platform: BigQuery (SQL)\n-- Medallion Layer: Bronze\n-- ================================================================\n```\n\n### 2. BRONZE LAYER PATTERN\n```sql\n-- Create Bronze table\nCREATE TABLE IF NOT EXISTS `{{ project_id }}.{{ bronze_dataset }}.{{ bronze_table }}` (\n    -- Source columns\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    \n    -- Bronze metadata\n    _ingestion_timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP(),\n    _source_file STRING,\n    _record_hash STRING\n)\nPARTITION BY DATE(_ingestion_timestamp)\nCLUSTER BY {{ cluster_columns }};\n\n-- Load data from Cloud Storage\nLOAD DATA INTO `{{ project_id }}.{{ bronze_dataset }}.{{ bronze_table }}`\nFROM FILES (\n    format = ''CSV'',\n    uris = [''{{ gcs_uri }}'']\n);\n\n-- Track row counts\nSELECT ''LOADED'' AS status, COUNT(*) AS row_count\nFROM `{{ project_id }}.{{ bronze_dataset }}.{{ bronze_table }}`\nWHERE _ingestion_timestamp >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 5 MINUTE);\n```\n\n### 3. VALIDATION\n- ✅ No hardcoded project/dataset/table\n- ✅ Partitioned by _ingestion_timestamp\n- ✅ Bronze metadata columns',
    true, 'agent-c', 'bigquery', 'bronze',
    '{"description": "BigQuery Bronze Layer cartridge (raw data ingestion)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 5. BigQuery Silver
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_bigquery_silver',
    E'# BigQuery SQL Silver Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS\n\n### 1. HEADER\n```sql\n-- ================================================================\n-- L2L MODERNIZATION TRACE: Silver Layer - {{asset_name}}\n-- Target Platform: BigQuery (SQL)\n-- Medallion Layer: Silver\n-- ================================================================\n```\n\n### 2. SILVER LAYER PATTERN\n```sql\n-- Create Silver table\nCREATE TABLE IF NOT EXISTS `{{ project_id }}.{{ silver_dataset }}.{{ silver_table }}` (\n    -- Business columns\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    _processed_timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP(),\n    _is_current BOOL DEFAULT TRUE\n)\nPARTITION BY DATE(_processed_timestamp);\n\n-- MERGE for SCD Type 1\nMERGE `{{ project_id }}.{{ silver_dataset }}.{{ silver_table }}` AS target\nUSING (\n    SELECT * FROM (\n        SELECT *, ROW_NUMBER() OVER (PARTITION BY {{business_key}} ORDER BY _ingestion_timestamp DESC) AS rn\n        FROM `{{ project_id }}.{{ bronze_dataset }}.{{ bronze_table }}`\n    ) WHERE rn = 1\n) AS source\nON {{merge_condition}}\nWHEN MATCHED THEN UPDATE SET *\nWHEN NOT MATCHED THEN INSERT *;\n```',
    true, 'agent-c', 'bigquery', 'silver',
    '{"description": "BigQuery Silver Layer cartridge (cleaned and deduplicated)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

