-- ================================================================
-- AWS GLUE CARTRIDGES (PySpark-Based - Similar to Databricks)
-- ================================================================

-- 7. AWS Glue Bronze
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_aws_glue_bronze',
    E'# AWS Glue PySpark Bronze Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS\n\n### 1. HEADER\n```python\n# ================================================================\n# L2L MODERNIZATION TRACE: Bronze Layer - {{asset_name}}\n# Target Platform: AWS Glue (PySpark + S3)\n# Medallion Layer: Bronze\n# ================================================================\n```\n\n### 2. AWS GLUE PATTERN\n```python\nimport sys\nfrom awsglue.transforms import *\nfrom awsglue.utils import getResolvedOptions\nfrom pyspark.context import SparkContext\nfrom awsglue.context import GlueContext\nfrom awsglue.job import Job\nfrom pyspark.sql import functions as F\n\nargs = getResolvedOptions(sys.argv, [''JOB_NAME'', ''bronze_path'', ''source_database'', ''source_table''])\n\nsc = SparkContext()\nglueContext = GlueContext(sc)\nspark = glueContext.spark_session\njob = Job(glueContext)\njob.init(args[''JOB_NAME''], args)\n\n# Read from Glue Data Catalog\ndf = glueContext.create_dynamic_frame.from_catalog(\n    database=args[''source_database''],\n    table_name=args[''source_table'']\n).toDF()\n\n# Add Bronze metadata\ndf_bronze = df \\\n    .withColumn("_ingestion_timestamp", F.current_timestamp()) \\\n    .withColumn("_source_file", F.lit(args.get(''source_file'', ''N/A''))) \\\n    .withColumn("_record_hash", F.sha2(F.concat_ws("||", *df.columns), 256))\n\n# Write to S3 as Parquet\ndf_bronze.write \\\n    .format("parquet") \\\n    .mode("append") \\\n    .save(args[''bronze_path''])\n\njob.commit()\n```\n\n### 3. VALIDATION\n- ✅ AWS Glue Context initialization\n- ✅ Read from Glue Data Catalog\n- ✅ Bronze metadata columns\n- ✅ Write to S3',
    true, 'agent-c', 'aws_glue', 'bronze',
    '{"description": "AWS Glue Bronze Layer cartridge (raw data ingestion)", "version": "4.0", "pyspark_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 8. AWS Glue Silver
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_aws_glue_silver',
    E'# AWS Glue PySpark Silver Layer Cartridge Rules\n\n## 🎯 SILVER LAYER PATTERN\n\n```python\nfrom awsglue.transforms import *\nfrom pyspark.sql.window import Window\n\n# Read from Bronze\ndf_bronze = spark.read.parquet(args[''bronze_path''])\n\n# Deduplication\nbusiness_keys = args[''business_keys''].split('','')\nwindow_spec = Window.partitionBy(*business_keys).orderBy(F.col("_ingestion_timestamp").desc())\n\ndf_silver = df_bronze \\\n    .withColumn("row_num", F.row_number().over(window_spec)) \\\n    .filter(F.col("row_num") == 1) \\\n    .drop("row_num") \\\n    .withColumn("_processed_timestamp", F.current_timestamp())\n\n# Write to S3\ndf_silver.write.format("parquet").mode("overwrite").save(args[''silver_path''])\n```',
    true, 'agent-c', 'aws_glue', 'silver',
    '{"description": "AWS Glue Silver Layer cartridge (cleaned and deduplicated)", "version": "4.0", "pyspark_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 9. AWS Glue Gold
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_aws_glue_gold',
    E'# AWS Glue PySpark Gold Layer Cartridge Rules\n\n## 🎯 GOLD LAYER PATTERN\n\n```python\n# Read from Silver\ndf_silver = spark.read.parquet(args[''silver_path''])\n\n# Apply business logic aggregations\ndf_gold = df_silver.groupBy(args[''group_by_columns''].split('','')) \\\n    .agg(*[eval(agg) for agg in args[''aggregations''].split('';'')]) \\\n    .withColumn("_gold_processed_timestamp", F.current_timestamp())\n\n# Write to S3\ndf_gold.write.format("parquet").mode("overwrite").save(args[''gold_path''])\n```',
    true, 'agent-c', 'aws_glue', 'gold',
    '{"description": "AWS Glue Gold Layer cartridge (business-ready aggregated data)", "version": "4.0", "pyspark_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- ================================================================
-- REDSHIFT CARTRIDGES (SQL-Based)
