-- 10. Redshift Bronze
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_redshift_bronze',
    E'# Redshift SQL Bronze Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS\n\n### 1. HEADER\n```sql\n-- ================================================================\n-- L2L MODERNIZATION TRACE: Bronze Layer - {{asset_name}}\n-- Target Platform: AWS Redshift (SQL)\n-- Medallion Layer: Bronze\n-- ================================================================\n```\n\n### 2. BRONZE LAYER PATTERN\n```sql\n-- Create Bronze table with distribution key\nCREATE TABLE IF NOT EXISTS {{ bronze_schema }}.{{ bronze_table }} (\n    -- Source columns\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    \n    -- Bronze metadata\n    _ingestion_timestamp TIMESTAMP DEFAULT GETDATE(),\n    _source_file VARCHAR(500),\n    _record_hash VARCHAR(64)\n)\nDISTKEY({{ distribution_key }})\nSORTKEY(_ingestion_timestamp);\n\n-- COPY from S3\nCOPY {{ bronze_schema }}.{{ bronze_table }}\nFROM ''{{ s3_uri }}''\nIAM_ROLE ''{{ iam_role }}''\nFORMAT AS CSV\nIGNOREHEADER 1\nTIMEFORMAT ''auto'';\n\n-- Track row counts\nSELECT ''LOADED'' AS status, COUNT(*) AS row_count\nFROM {{ bronze_schema }}.{{ bronze_table }}\nWHERE _ingestion_timestamp >= DATEADD(minute, -5, GETDATE());\n```\n\n### 3. VALIDATION\n- ✅ DISTKEY for distribution\n- ✅ SORTKEY for query performance\n- ✅ COPY command from S3',
    true, 'agent-c', 'redshift', 'bronze',
    '{"description": "Redshift Bronze Layer cartridge (raw data ingestion)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 11. Redshift Silver
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_redshift_silver',
    E'# Redshift SQL Silver Layer Cartridge Rules\n\n## 🎯 SILVER LAYER PATTERN\n\n```sql\nCREATE TABLE IF NOT EXISTS {{ silver_schema }}.{{ silver_table }} (\n    {{#each columns}}\n    {{name}} {{data_type}},\n    {{/each}}\n    _processed_timestamp TIMESTAMP DEFAULT GETDATE(),\n    _is_current BOOLEAN DEFAULT TRUE\n)\nDISTKEY({{ distribution_key }})\nSORTKEY({{ business_key }});\n\n-- Merge logic (Redshift doesn''t support MERGE, use DELETE+INSERT)\nBEGIN TRANSACTION;\n\nDELETE FROM {{ silver_schema }}.{{ silver_table }}\nWHERE {{ business_key }} IN (\n    SELECT DISTINCT {{ business_key }}\n    FROM {{ bronze_schema }}.{{ bronze_table }}\n    WHERE _ingestion_timestamp > ''{{ last_run_timestamp }}''\n);\n\nINSERT INTO {{ silver_schema }}.{{ silver_table }}\nSELECT DISTINCT ON ({{ business_key }})\n    *,\n    GETDATE() AS _processed_timestamp,\n    TRUE AS _is_current\nFROM {{ bronze_schema }}.{{ bronze_table }}\nWHERE _ingestion_timestamp > ''{{ last_run_timestamp }}''\nORDER BY {{ business_key }}, _ingestion_timestamp DESC;\n\nCOMMIT;\n```',
    true, 'agent-c', 'redshift', 'silver',
    '{"description": "Redshift Silver Layer cartridge (cleaned and deduplicated)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

-- 12. Redshift Gold
INSERT INTO public.utm_prompts (
    prompt_id, content, is_active, agent_id, tech_stack, pattern_type, metadata, created_at, updated_at
) VALUES (
    'cartridge_redshift_gold',
    E'# Redshift SQL Gold Layer Cartridge Rules\n\n## 🎯 GOLD LAYER PATTERN\n\n```sql\nCREATE TABLE IF NOT EXISTS {{ gold_schema }}.{{ gold_table }} AS\nSELECT\n    {{#each aggregations}}\n    {{expression}} AS {{alias}},\n    {{/each}}\n    GETDATE() AS _gold_processed_timestamp\nFROM {{ silver_schema }}.{{ silver_table }}\nGROUP BY {{group_by_columns}};\n\n-- Optimize with VACUUM and ANALYZE\nVACUUM {{ gold_schema }}.{{ gold_table }};\nANALYZE {{ gold_schema }}.{{ gold_table }};\n```',
    true, 'agent-c', 'redshift', 'gold',
    '{"description": "Redshift Gold Layer cartridge (business-ready aggregated data)", "version": "4.0", "sql_based": true}'::jsonb,
    NOW(), NOW()
) ON CONFLICT (prompt_id) DO UPDATE SET content = EXCLUDED.content, updated_at = NOW();

