-- List all cartridge prompts
SELECT 
    prompt_id,
    tech_stack,
    pattern_type,
    LENGTH(content) as chars,
    metadata->>'sql_based' as sql_based,
    metadata->>'pyspark_based' as pyspark_based,
    is_active
FROM public.utm_prompts
WHERE prompt_id LIKE 'cartridge_%'
ORDER BY tech_stack, pattern_type;
